<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';require_admin();require __DIR__.'/_layout.php';$allowed=['Menunggu pembayaran','Diproses','Dikirim','Selesai','Dibatalkan'];$q=trim($_GET['q']??'');$status=$_GET['status']??'';$page=max(1,(int)($_GET['page']??1));$limit=20;$where=[];$args=[];if($q!==''){$where[]='(order_number LIKE ? OR customer_name LIKE ? OR email LIKE ? OR phone LIKE ?)';array_push($args,"%$q%","%$q%","%$q%","%$q%");}if(in_array($status,$allowed,true)){$where[]='status=?';$args[]=$status;}$clause=$where?' WHERE '.implode(' AND ',$where):'';$st=$pdo->prepare('SELECT COUNT(*) FROM orders'.$clause);$st->execute($args);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$st=$pdo->prepare('SELECT id,order_number,customer_name,email,phone,total,status,created_at FROM orders'.$clause.' ORDER BY id DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$st->execute($args);$rows=$st->fetchAll();admin_header('Pesanan');?><main class="adminmain"><div class="adminhead"><div><span class="eyebrow">TRANSAKSI TOKO</span><h1>Daftar pesanan</h1></div><span class="muted"><?=$total?> pesanan</span></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Cari no. pesanan, nama, email, telepon"><select name="status"><option value="">Semua status</option><?php foreach($allowed as $s):?><option value="<?=e($s)?>" <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach?></select><button class="smallbtn">Filter</button><a href="orders.php">Reset</a></form><div class="tablewrap"><table class="admintable"><thead><tr><th>No. pesanan</th><th>Pelanggan</th><th>Kontak</th><th>Total</th><th>Status</th><th>Waktu</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['order_number'])?></td><td><?=e($r['customer_name'])?></td><td><?=e($r['email'])?><br><?=e($r['phone'])?></td><td><?=rupiah($r['total'])?></td><td><span class="status-pill"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td><td><a href="order.php?id=<?=$r['id']?>">Buka</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7">Tidak ada pesanan yang cocok.</td></tr><?php endif?></tbody></table></div><div class="pagination"><?php for($n=1;$n<=$pages;$n++):?><a href="?<?=http_build_query(['q'=>$q,'status'=>$status,'page'=>$n])?>" <?=$n===$page?'style="font-weight:700;background:#e9eee9"':''?>><?=$n?></a><?php endfor?></div></main><?php admin_footer();?>